import type { Candidate } from './candidate';
import type { HealthCheckSpec, HealthStageResult } from './health-checker.port';

/**
 * What crosses the port boundary in either direction. `raw` is the only
 * field a specific backend's serialized config lives in (TOML for MTG,
 * something else for a future backend) — the application layer treats it
 * as an opaque blob it stores/restores byte-for-byte via `BackupStore` and
 * never parses or interpolates itself. `domain`/`port`/`secret` are pulled
 * out because the use case and the Telegram report genuinely need them
 * without caring about the backend's file format.
 */
export interface ProviderConfig {
  readonly domain: string;
  readonly port: number;
  readonly secret: string;
  readonly raw: string;
}

export interface InfraStatus {
  readonly containerRunning: HealthStageResult;
  readonly portListening: HealthStageResult;
}

/**
 * Port for "run and manage one MTProto backend". `MTGProvider` is the only
 * implementation; a future backend swap means a new class implementing
 * this interface and a one-line change in the composition root — nothing
 * in `application/` should need to change. `checkInfra()` covers health
 * stages 1-2 (container/port) because only the provider knows what
 * "running" means for its own backend (a Docker container today, maybe a
 * systemd unit for a different backend tomorrow); stages 3-4 are
 * `HealthChecker`'s job instead — see that port's own comment.
 */
export interface MtprotoProvider {
  readonly name: string;
  /**
   * Async on purpose, unlike a pure in-memory builder: a correct fake-TLS
   * secret is generated by shelling out to the real `mtg generate-secret`
   * (confirmed against MTG's own README, 2026-08-04) rather than this
   * project reimplementing its exact byte layout — a version-format drift
   * in a hand-rolled encoder would be a silent, hard-to-notice bug in
   * exactly the field a censor is trying to fingerprint.
   */
  generateConfig(candidate: Candidate): Promise<ProviderConfig>;
  /** `undefined` if nothing has ever been applied on this host yet — a legal, expected state, not an error. */
  currentConfig(): Promise<ProviderConfig | undefined>;
  apply(config: ProviderConfig): Promise<void>;
  restart(): Promise<void>;
  checkInfra(): Promise<InfraStatus>;
  healthCheckSpec(config: ProviderConfig): HealthCheckSpec;
}
